import{_ as a,o as i,c as l,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"模板帳單匯入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/01-template-bill-import-guide.md","filePath":"v1/zh-HK/guide/01-template-bill-import-guide.md"}'),s={name:"v1/zh-HK/guide/01-template-bill-import-guide.md"};function e(o,t,n,h,d,p){return i(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="模板帳單匯入指南" tabindex="-1">模板帳單匯入指南 <a class="header-anchor" href="#模板帳單匯入指南" aria-label="Permalink to &quot;模板帳單匯入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉記帳支援從外部檔案匯入帳單資料，方便你快速搬移歷史帳單。目前支援以下匯入方式：</p><ul><li><strong>模板檔案匯入</strong>：使用標準格式的 CSV 檔案匯入</li><li><strong>微信帳單匯入</strong>：直接匯入微信匯出的帳單檔案</li><li><strong>支付寶帳單匯入</strong>：直接匯入支付寶匯出的帳單檔案</li><li><strong>貔貅記帳匯入</strong>：直接匯入貔貅記帳 App 匯出的 CSV 帳單檔</li><li><strong>iCost 匯入</strong>：直接匯入 iCost App 匯出的 xlsx 檔案</li></ul><hr><h2 id="📁-支援的檔案格式" tabindex="-1">📁 支援的檔案格式 <a class="header-anchor" href="#📁-支援的檔案格式" aria-label="Permalink to &quot;📁 支援的檔案格式&quot;">​</a></h2><ul><li><strong>CSV 檔</strong>（<code>.csv</code>）：支付寶、貔貅、模板帳單</li><li><strong>Excel 檔</strong>（<code>.xlsx</code>、<code>.xls</code>）：微信帳單、iCost 帳單</li></ul><hr><h2 id="🚀-快速開始" tabindex="-1">🚀 快速開始 <a class="header-anchor" href="#🚀-快速開始" aria-label="Permalink to &quot;🚀 快速開始&quot;">​</a></h2><h3 id="步驟-1-進入匯入頁面" tabindex="-1">步驟 1：進入匯入頁面 <a class="header-anchor" href="#步驟-1-進入匯入頁面" aria-label="Permalink to &quot;步驟 1：進入匯入頁面&quot;">​</a></h3><ol><li>打開考拉記帳 App</li><li>點擊底部導覽列的 <strong>「設定」</strong></li><li>在設定頁面中找到 <strong>「帳單匯入」</strong></li><li>點擊進入帳單匯入頁面</li></ol><h3 id="步驟-2-選擇匯入來源" tabindex="-1">步驟 2：選擇匯入來源 <a class="header-anchor" href="#步驟-2-選擇匯入來源" aria-label="Permalink to &quot;步驟 2：選擇匯入來源&quot;">​</a></h3><p>在匯入頁面中，請選擇帳單來源類型：</p><ul><li><strong>模板檔案</strong>：適用於標準格式的 CSV</li><li><strong>微信</strong>：適用於微信匯出的帳單檔</li><li><strong>支付寶</strong>：適用於支付寶匯出的帳單檔</li><li><strong>貔貅記帳</strong>：適用於貔貅記帳匯出的帳單檔</li><li><strong>iCost</strong>：適用於 iCost 匯出的帳單檔</li></ul><blockquote><p>⚠️ <strong>重要</strong>：請務必選擇正確的匯入來源，否則可能導致解析失敗。</p></blockquote><h3 id="步驟-3-選擇檔案" tabindex="-1">步驟 3：選擇檔案 <a class="header-anchor" href="#步驟-3-選擇檔案" aria-label="Permalink to &quot;步驟 3：選擇檔案&quot;">​</a></h3><ol><li>點擊 <strong>「檔案路徑」</strong></li><li>在檔案選擇器中選擇要匯入的檔案</li><li>確認已選擇檔案（會顯示檔名）</li></ol><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>檔案必須保存在裝置本機（可透過檔案管理器存取）</li><li>確保檔案格式正確（CSV 或 xlsx）</li><li>確保檔案未損壞</li></ul></blockquote><h3 id="步驟-4-關聯帳本" tabindex="-1">步驟 4：關聯帳本 <a class="header-anchor" href="#步驟-4-關聯帳本" aria-label="Permalink to &quot;步驟 4：關聯帳本&quot;">​</a></h3><ol><li>點擊 <strong>「關聯帳本」</strong></li><li>選擇要把帳單匯入到哪個帳本</li><li>確認帳本選擇</li></ol><blockquote><p>💡 <strong>提示</strong>：如果只有一個帳本，系統會自動關聯到預設帳本。</p></blockquote><h3 id="步驟-5-解析檔案" tabindex="-1">步驟 5：解析檔案 <a class="header-anchor" href="#步驟-5-解析檔案" aria-label="Permalink to &quot;步驟 5：解析檔案&quot;">​</a></h3><ol><li>點擊右上角 <strong>「解析」</strong></li><li>等待系統解析（可能需要幾秒）</li><li>解析成功後會自動跳轉到預覽頁</li></ol><blockquote><p>⚠️ <strong>如果解析失敗</strong>：</p><ul><li>檢查檔案格式是否正確</li><li>檢查是否選擇了正確的匯入來源</li><li>檢查檔案是否損壞</li><li>嘗試重新匯出檔案</li></ul></blockquote><h3 id="步驟-6-預覽與編輯" tabindex="-1">步驟 6：預覽與編輯 <a class="header-anchor" href="#步驟-6-預覽與編輯" aria-label="Permalink to &quot;步驟 6：預覽與編輯&quot;">​</a></h3><p>解析成功後，你可以在預覽頁：</p><ul><li><strong>查看所有帳單記錄</strong>：按日期分組顯示</li><li><strong>編輯單筆記錄</strong>：點擊記錄可修改分類、金額、時間等</li><li><strong>刪除無效記錄</strong>：長按記錄可刪除</li><li><strong>批量操作</strong>：可選擇跳過無效記錄</li></ul><blockquote><p>📝 <strong>建議</strong>：匯入前先預覽資料，確認無誤再匯入。</p></blockquote><h3 id="步驟-7-匯入資料" tabindex="-1">步驟 7：匯入資料 <a class="header-anchor" href="#步驟-7-匯入資料" aria-label="Permalink to &quot;步驟 7：匯入資料&quot;">​</a></h3><ol><li>在預覽頁確認資料無誤後</li><li>點擊 <strong>「匯入」</strong></li><li>等待匯入完成</li><li>匯入成功後會顯示匯入結果</li></ol><hr><h2 id="📝-模板檔案格式說明" tabindex="-1">📝 模板檔案格式說明 <a class="header-anchor" href="#📝-模板檔案格式說明" aria-label="Permalink to &quot;📝 模板檔案格式說明&quot;">​</a></h2><p>如要使用模板匯入，請依照以下格式準備 CSV 檔案。</p><h3 id="csv-格式要求" tabindex="-1">CSV 格式要求 <a class="header-anchor" href="#csv-格式要求" aria-label="Permalink to &quot;CSV 格式要求&quot;">​</a></h3><ol><li><strong>檔案編碼</strong>：支援 UTF-8 或 GBK</li><li><strong>分隔符</strong>：使用逗號 <code>,</code></li><li><strong>表頭</strong>：第一行必須包含表頭</li></ol><h3 id="標準格式示例" tabindex="-1">標準格式示例 <a class="header-anchor" href="#標準格式示例" aria-label="Permalink to &quot;標準格式示例&quot;">​</a></h3><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">類型,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">金額,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">分類,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">帳戶,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">備註,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">標籤</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">支出,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">100.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">餐飲,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">現金,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">午餐,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">工作餐</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-02,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">收入,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">5000.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">工資,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">銀行卡,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">月薪,</span></span></code></pre></div><h3 id="欄位說明" tabindex="-1">欄位說明 <a class="header-anchor" href="#欄位說明" aria-label="Permalink to &quot;欄位說明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>欄位</th><th>說明</th><th>必填</th><th>示例</th></tr></thead><tbody><tr><td>交易日期</td><td>帳單日期，格式：<code>yyyy/MM/dd</code></td><td>✅</td><td>2026/01/01</td></tr><tr><td>交易分類</td><td>支出或收入</td><td>✅</td><td>支出 / 收入</td></tr><tr><td>收支大類</td><td>一級分類名稱</td><td>✅</td><td>伙食</td></tr><tr><td>收支小類</td><td>二級分類名稱（隸屬於一級分類）</td><td>✅</td><td>早餐</td></tr><tr><td>流入金額</td><td>收入金額欄位（交易分類為收入時填寫）</td><td>✅</td><td>100.00</td></tr><tr><td>流出金額</td><td>支出金額欄位（交易分類為支出時填寫）</td><td>✅</td><td>15</td></tr><tr><td>資金帳戶</td><td>帳戶名稱（盡量填寫 App 內已存在的帳戶）</td><td>✅</td><td>預設帳戶</td></tr><tr><td>備註</td><td>帳單備註</td><td>❌</td><td>午餐</td></tr><tr><td>標籤</td><td>標籤名稱，多個以逗號分隔</td><td>❌</td><td>工作餐,聚餐</td></tr></tbody></table><h3 id="下載模板檔案" tabindex="-1">下載模板檔案 <a class="header-anchor" href="#下載模板檔案" aria-label="Permalink to &quot;下載模板檔案&quot;">​</a></h3><ol><li>在匯入頁面點擊 <strong>「下載模板檔案」</strong></li><li>系統會下載示例 CSV 檔</li><li>你可參考模板格式準備自己的資料</li></ol><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><h3 id="_1-資料格式要求" tabindex="-1">1. 資料格式要求 <a class="header-anchor" href="#_1-資料格式要求" aria-label="Permalink to &quot;1. 資料格式要求&quot;">​</a></h3><ul><li><strong>日期格式</strong>：必須為 <code>YYYY/MM/DD</code>（例如：<code>2026/01/01</code>）</li><li><strong>金額格式</strong>：必須為數字，支援小數點（例如：<code>100.00</code>）</li><li><strong>交易分類</strong>：必須為「支出」或「收入」</li><li><strong>分類與帳戶</strong>：若 App 中不存在，匯入時可能會自動建立</li></ul><h3 id="_2-資料驗證" tabindex="-1">2. 資料驗證 <a class="header-anchor" href="#_2-資料驗證" aria-label="Permalink to &quot;2. 資料驗證&quot;">​</a></h3><p>匯入前，系統會自動驗證資料：</p><ul><li>✅ <strong>有效記錄</strong>：格式正確，可正常匯入</li><li>⚠️ <strong>無效記錄</strong>：格式錯誤，需要修改</li><li>❌ <strong>跳過記錄</strong>：可跳過無效記錄，只匯入有效資料</li></ul><h3 id="_3-重複資料處理" tabindex="-1">3. 重複資料處理 <a class="header-anchor" href="#_3-重複資料處理" aria-label="Permalink to &quot;3. 重複資料處理&quot;">​</a></h3><ul><li>建議匯入前先檢查是否有重複資料</li></ul><h3 id="_4-大量資料匯入" tabindex="-1">4. 大量資料匯入 <a class="header-anchor" href="#_4-大量資料匯入" aria-label="Permalink to &quot;4. 大量資料匯入&quot;">​</a></h3><ul><li>資料量很大（例如超過 1000 筆）建議分批匯入</li><li>匯入過程請保持 App 在前台</li><li>匯入完成後，建議手動同步一次資料</li></ul><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-解析失敗怎麼辦" tabindex="-1">Q1：解析失敗怎麼辦？ <a class="header-anchor" href="#q1-解析失敗怎麼辦" aria-label="Permalink to &quot;Q1：解析失敗怎麼辦？&quot;">​</a></h3><p>請檢查：</p><ol><li>檔案格式是否正確（CSV 或 xlsx）</li><li>是否選擇了正確的匯入來源</li><li>檔案是否損壞</li><li>檔案編碼是否正確（建議 UTF-8）</li></ol><h3 id="q2-匯入後資料不完整" tabindex="-1">Q2：匯入後資料不完整？ <a class="header-anchor" href="#q2-匯入後資料不完整" aria-label="Permalink to &quot;Q2：匯入後資料不完整？&quot;">​</a></h3><p>可能原因：</p><ol><li>部分記錄格式錯誤，被系統跳過</li><li>分類或帳戶不存在，需要先建立</li><li>建議在預覽頁檢查無效記錄</li></ol><h3 id="q3-可以匯入圖片嗎" tabindex="-1">Q3：可以匯入圖片嗎？ <a class="header-anchor" href="#q3-可以匯入圖片嗎" aria-label="Permalink to &quot;Q3：可以匯入圖片嗎？&quot;">​</a></h3><p>目前不支援。</p><h3 id="q4-匯入後可以修改嗎" tabindex="-1">Q4：匯入後可以修改嗎？ <a class="header-anchor" href="#q4-匯入後可以修改嗎" aria-label="Permalink to &quot;Q4：匯入後可以修改嗎？&quot;">​</a></h3><p>可以。匯入後你可在帳單列表中編輯或刪除記錄。</p><h3 id="q5-支援一次匯入多個檔案嗎" tabindex="-1">Q5：支援一次匯入多個檔案嗎？ <a class="header-anchor" href="#q5-支援一次匯入多個檔案嗎" aria-label="Permalink to &quot;Q5：支援一次匯入多個檔案嗎？&quot;">​</a></h3><p>目前不支援。每次只能匯入一個檔案，多個檔案請逐個匯入。</p><hr><h2 id="📚-相關教學" tabindex="-1">📚 相關教學 <a class="header-anchor" href="#📚-相關教學" aria-label="Permalink to &quot;📚 相關教學&quot;">​</a></h2><ul><li><a href="./02-wechat-bill-import-guide">微信帳單匯入教程</a></li><li><a href="./03-alipay-bill-import-guide">支付寶帳單匯入教程</a></li><li><a href="./04-multi-ledger-guide">多帳本功能說明</a></li></ul><hr><p><strong>最後更新</strong>：2026 年 1 月</p>`,71)])])}const u=a(s,[["render",e]]);export{c as __pageData,u as default};
